n("סוהיל", "סוהיל הוא השם הערבי של כוכב בהיר שנראה נמוך בשמיים הדרומיים, ובאסטרונומיה של היום הוא מוכר בשם קנופוס. בתרבות הערבית הכוכב קשור לסוף הקיץ, כי הוא מופיע בשמיים של חצי האי ערב לקראת סוף העונה החמה. כשם, סוהיל מביא תמונה של אור רחוק ויציב בלילה.")
n("סיון", "סיון הוא אחד מחודשי הלוח העברי, ובו חל חג השבועות. שמות החודשים העבריים הגיעו מהלוח הבבלי, ובתנ״ך סיון נזכר במגילת אסתר. החודש חל בסוף האביב ובתחילת הקיץ, בזמן הקציר של החיטה, והשם נכתב גם סיוון, בשתי אותיות ו.")
n("עאסם", "עאסם הוא שם ערבי שפירושו מגן ושומר, מי ששומר על אחרים ועומד לצידם. הוא בנוי על פועל ערבי שעניינו שמירה והגנה, ומאותו שורש בא בערבית גם השם עיסאם. השם מתאר את מעשה השמירה עצמו, כמו שמות ערביים נוספים שנבנו על פעולה.")
n("עיישה", "עיישה היא צורה של השם הערבי עאישה, שבא מהשורש ע־י־ש, שעניינו חיים, ופירושו מי שחיה. בערבית של מצרים המילה עיש פירושה גם לחם, הדבר שחיים ממנו. הכתיב עיישה קרוב יותר לאופן שבו השם נשמע בדיבור.", ["עאישה"])
n("עילם", "עילם היא ארץ עתיקה ממזרח לבבל, באזור שהיום נמצא בדרום־מערב איראן. בתנ״ך עילם הוא גם שם של אדם, אחד מבני שם, ושמה של הארץ קשור לשמו. בעברית השם נכתב באות י אחרי העין, כמו שהוא מופיע במקרא.")
n("פאיזה", "פאיזה היא צורת הנקבה של השם הערבי פאיז, שפירושו מנצח, מי שזוכה. השם בא מהשורש הערבי פ־ו־ז, שעניינו ניצחון והצלחה, ומאותו שורש באה גם המילה פוז, ניצחון. בערבית של היום המילה פאיז משמשת גם לתיאור של מי שזכה בתחרות או בפרס.", ["פאיז"])
n("פדות", "פדות היא מילה עברית עתיקה מהשורש פ־ד־ה, שעניינו שחרור והצלה, כמו במילים פדיון ופודה. במקרא המילה מופיעה בשירה, כמילה לגאולה שנשלחת לעם. כשם, פדות מביא את הרעיון של יציאה לחופש.")
n("פידא", "פידא היא מילה ערבית מהשורש פ־ד־י, שהוא אותו שורש של המילים העבריות פדיון ופדות. בערבית המילה מתארת הקרבה של דבר יקר למען אחר, וגם פדיון ושחרור. השורש משותף לשתי השפות, ובשתיהן עניינו מסירה של דבר אחד כדי להציל דבר אחר.")
n("פריידי", "פריידי היא צורת חיבה של השם היידי פריידא, שבא מהמילה היידית פרייד, שמחה. ביידיש מקובל להוסיף לשמות את הסיומת ־י כדי ליצור צורה קטנה וחמה של השם. מאותה מילה בגרמנית באה המילה פרוידה, שגם פירושה שמחה.", ["פריידא"])
n("צליל", "צליל הוא קול אחד וברור, כמו קול של תו בנגינה או של פעמון. המילה באה מהשורש צ־ל־ל, ומאותו שורש באות גם המילים צלצול ומצלתיים. בעברית של היום משתמשים בה גם לתיאור של קול שנשמע נקי ויפה.")
n("קיארה", "קיארה היא המילה האיטלקית לבהירה וצלולה, והיא באה מהמילה הלטינית קלרוס, בהיר ומאיר. מאותה מילה לטינית בא גם השם קלרה, שמוכר בשפות רבות של אירופה. כשם, קיארה מביא תמונה של אור צלול ושל שמיים נקיים.")
n("קיילי", "קיילי הוא שם באנגלית, שמקורו בשמות ממקור אירי. ההסברים למשמעות שלו שונים, ואין ביניהם הסבר אחד מקובל. בעברית השם נכתב כמו שהוא נשמע באנגלית, עם שתי אותיות י אחרי הקוף.")
n("רגב", "רגב הוא גוש קטן של אדמה, כמו אלה שנשארים בשדה אחרי החריש. המילה עתיקה, ובמקרא היא מופיעה בצורת הרבים, רגבים, בתיאור של עפר שנדבק לגושים. בעברית של היום משתמשים בצירוף רגבי אדמה גם לתיאור של קשר לארץ ולאדמה.")
n("רויזא", "רויזא הוא שם יידי שבא מהמילה היידית רויז, ורד, והוא הצורה היידית של השם רוזה, שמוכר בשפות רבות. ביידיש יש לשם גם צורת חיבה, רייזל, ורד קטן. השם מצטרף לשמות רבים שנבנו על שם של פרח.", ["רוזה", "רוזא", "רייזל"])
n("רותי", "רותי היא צורת חיבה של השם רות, עם הסיומת ־י, שמוסיפה לשם נימה קרובה וחמה. את השם רות מקובל לקשר למילה רעות, קשר קרוב בין חברים. עם השנים רותי נעשתה שם בפני עצמו, שמשמש גם בלי השם המלא.", ["רות"])
n("רפיק", "רפיק היא המילה הערבית לחבר, מי שהולך יחד עם מישהו בדרך. השורש הערבי ר־פ־ק עניינו ליווי ועדינות, ומאותו שורש באה גם המילה רפקה, חבורה של אנשים שהולכים יחד. בערבית של היום המילה משמשת גם כפנייה לחבר קרוב, וגם במשמעות של שותף לדרך.")
n("שיינדי", "שיינדי היא צורת חיבה של השם היידי שיינדל, שבא מהמילה היידית שיין, יפה. ביידיש מקובל ליצור צורות קטנות וחמות של שמות, ושיינדי היא אחת מהן. מאותה מילה נבנו גם השמות שיינא ושיינדל.", ["שיינדל", "שינדל"])
n("שמעיה", "שמעיה בנוי מהמילה שמע ומיה, הצורה הקצרה של שם ה׳, ופירושו ה׳ שמע. בתנ״ך נקראים כך כמה אנשים, ואחד מהם הוא שמעיה איש האלוהים, נביא בימי רחבעם. השם שייך לקבוצה של שמות שמחברים פועל עם שם ה׳, כמו זכריה ונתניה.")
n("שריה", "שריה בנוי מהשורש ש־ר־ה, שעניינו שלטון וכוח, ומיה, הצורה הקצרה של שם ה׳, ופירושו ה׳ שולט. בתנ״ך נקראים כך כמה אנשים, ואחד מהם היה סופר בחצר של דוד המלך. השם נכתב באות שין שמאלית, כמו המילים שר ושררה.")
n("תלם", "תלם הוא החריץ הארוך שהמחרשה פותחת באדמה, ושבו זורעים את הזרעים. בשדה חרוש התלמים עוברים זה לצד זה בשורות ישרות. בעברית של היום משתמשים במילה גם בביטוי ללכת בתלם, ללכת בדרך המקובלת.", ["תלמה"])
n("אבי", "אבי פירושו האב שלי, והוא בנוי על המילה אב עם הסיומת ־י, כמו בשמות אביגיל ואביטל. אבי משמש גם צורה קצרה של אברהם ושל שמות ארוכים שמתחילים באבי, כמו אביגדור ואבישי. עם השנים אבי נעשה שם בפני עצמו, גם בלי שם מלא.", ["אברהם", "אביגדור"])
n("אדוארד", "אדוארד הוא שם אנגלי עתיק, שבנוי משתי מילים באנגלית העתיקה, עושר ושומר, ופירושו שומר העושר. השם מוכר בשפות רבות של אירופה, ובכל אחת הוא נשמע מעט אחרת, כמו אדואר בצרפתית ואדוארדו באיטלקית. צורות החיבה המוכרות שלו באנגלית הן אד ואדי.")
n("אהוביה", "אהוביה בנוי מהמילה אהוב ומיה, הצורה הקצרה של שם ה׳, ופירושו אהובו של ה׳. השם נבנה כמו שמות עבריים ותיקים שמחברים מילה עם שם ה׳, כמו ידידיה, שגם פירושו קרוב. מאותה מילה נבנו גם השמות אהובה ואהבה.", ["אהובה"])
n("אידריס", "אידריס הוא שם ערבי, שמוכר מהמסורת המוסלמית. מקובל לקשר אותו לשורש הערבי ד־ר־ס, שעניינו לימוד, אבל זה הסבר עממי, ומקור השם לא ברור. בעברית הוא נכתב גם אדריס, באותה הגייה.", ["אדריס"])
n("אלירן", "אלירן בנוי מהמילה אלי, אלוהיי, ומהמילה רן, ופירושו אלוהיי שר ושמח. רן בא מהשורש ר־נ־נ, שעניינו שירה ושמחה, כמו במילים רינה ורננה. השם נבנה בעברית החדשה, כמו שמות נוספים שמחברים את אלי עם מילה אחרת, כמו אליאור ואלירז.", ["רן"])
n("אלישמע", "אלישמע בנוי מהמילה אלי, אלוהיי, ומהפועל שמע, ופירושו אלוהיי שמע. בתנ״ך נקראים כך כמה אנשים, ואחד מהם הוא נשיא שבט אפרים במדבר. אותו רעיון נמצא גם בשם שמעיה, שבו שם ה׳ בא בסוף השם.")
n("אמבר", "אמבר היא המילה האנגלית לענבר, שרף עתיק של עצים שהתקשה במשך זמן רב ונעשה לאבן שקופה בצבע זהוב וחום. המילה האנגלית הגיעה מהערבית, ומאותה מילה ערבית בא גם השם העברי ענבר. באנגלית אמבר הוא גם שם של צבע, כתום וזהוב.")
n("אנג'לה", "אנג'לה הוא שם שבא מהמילה היוונית אנגלוס, שליח, שבשפות של אירופה נעשתה למילה מלאך. השם מוכר בשפות רבות, ובאיטלקית ובאנגלית הוא נכתב כמעט באותה צורה. גם המילה העברית מלאך באה משורש שעניינו שליחות, כך שבשתי השפות המלאך הוא שליח.")
n("אסאלה", "אסאלה היא מילה ערבית שפירושה אצילות ומקוריות, דבר שהוא אמיתי ולא חיקוי. השורש הערבי א־צ־ל עניינו שורש ומקור, ומאותו שורש באה גם המילה אסיל, שמתארת דבר מגזע טוב ומקורי. כשם, אסאלה מביא את הרעיון של קשר לשורשים.")
n("ברית", "ברית היא הסכם והבטחה בין שני צדדים, שמחייבים את עצמם זה כלפי זה. בתנ״ך הקשת בענן היא אות לברית, אחרי המבול. בעברית של היום המילה משמשת גם במשמעות של חיבור קרוב בין אנשים, כמו בצירוף ברית ידידות.")
n("ג'ויס", "ג'ויס הוא שם אנגלי עתיק, שבימי הביניים נבנה על שם ממקור קלטי, ובאנגלית מקובל לקשר אותו לשמחה. באנגלית המילה ג'וי פירושה שמחה, והקרבה בצליל בין המילים חיזקה את הקשר הזה. השם מוכר באנגלית גם כשם פרטי וגם כשם משפחה.")
n("ג'וליאן", "ג'וליאן הוא שם שמקורו בשם הרומי יוליאנוס, שנבנה על שם המשפחה הרומי יוליוס. השם מוכר בשפות רבות של אירופה, ובכל אחת הוא נשמע מעט אחרת, כמו ג'וליאן באנגלית וז'וליאן בצרפתית. מאותו מקור באים גם השמות יוליה וג'וליה.")
n("ג'ון", "ג'ון הוא הצורה האנגלית של יוחנן, שם עברי שפירושו ה׳ חנן. השם עבר מהעברית ליוונית וללטינית, ומשם לשפות רבות של אירופה, ובכל אחת הוא קיבל צורה אחרת, כמו יאן, ז'אן וחואן. באנגלית השם התקצר עם הזמן, ונשאר ממנו רק חלק קטן מהשם המקורי.", ["יוחנן", "יאן", "שון"])
n("גליקא", "גליקא הוא שם יידי שבא מהמילה היידית גליק, מזל ואושר. המילה קרובה למילה הגרמנית גליק, שגם בה פירושה מזל ואושר. ביידיש שמות רבים נבנו על מילים של ברכה ושל טוב, ומאותה מילה נבנו גם צורות חיבה של השם.")
n("דובער", "דובער הוא שם יידי שמחבר את המילה העברית דב עם המילה היידית בער, ששתיהן פירושן דב. ביידיש מקובלים שמות כפולים כאלה, שבהם מילה עברית ומילה יידית אומרות את אותו הדבר, כמו צבי־הירש וזאב־וולף. בצורה המקוצרת השם נשמע בער או דוב.")
n("הלליה", "הלליה בנוי מהמילה הלל ומיה, הצורה הקצרה של שם ה׳, ופירושו שבח לה׳. הוא קרוב למילה הללויה, שפירושה הללו את ה׳, ומוכרת היטב מהשירה העתיקה. מאותו שורש, ה־ל־ל, באים גם השמות הלל והללי.", ["הלל", "הללי"])
n("ואטן", "ואטן היא המילה הערבית למולדת, המקום שאדם בא ממנו ומרגיש שייך אליו. המילה באה מהשורש הערבי ו־ט־נ, שעניינו מגורים והתיישבות במקום. כשם, ואטן מביא תמונה של בית ושל שייכות למקום.")
n("ודאד", "ודאד היא מילה ערבית שפירושה אהבה וחיבה, קשר חם בין אנשים. היא באה מהשורש הערבי ו־ד־ד, שקרוב לשורש העברי י־ד־ד, ממנו באות המילים ידיד וידידות. השם נכתב בעברית גם וידאד, באותה משמעות.")
n("ורוד", "ורוד היא צורת הרבים של המילה הערבית ורד, שפירושה פרח הוורד, ולכן פירוש השם ורדים. המילה משותפת לערבית ולעברית, ובשתי השפות ורד הוא שם של הפרח. בעברית המילה ורוד היא גם שם של צבע, אבל כשם ערבי היא נקראת בהגייה אחרת.", ["וורוד"])
n("חמדאן", "חמדאן הוא שם ערבי שבא מהשורש ח־מ־ד, שעניינו שבח ותודה, ופירושו מי שמשבח ומודה. מאותו שורש נבנו בערבית גם אחמד, מחמוד ומוחמד. בעברית השורש הזה קשור למילה חמדה, דבר יפה ונחמד, אבל המשמעות שלו בערבית שונה.")
n("חנן", "חנן בא מהשורש ח־נ־נ, שעניינו חן וחסד, ופירושו ה׳ חנן, נתן מתנה בחסד. בתנ״ך נקראים כך כמה אנשים, ברשימות של משפחות ושל שבטים. מאותו שורש נבנו גם השמות יוחנן, חננאל וחנניה, שבהם שם ה׳ מופיע במפורש.", ["יוחנן", "חננאל", "חנניה"])
n("ידיד", "ידיד הוא חבר אהוב וקרוב, ובעברית המילה מתארת קשר חם ונאמן בין אנשים. היא באה מהשורש י־ד־ד, שעניינו אהבה, ומאותו שורש באות גם המילים ידידות וידידה. על אותה מילה נבנה גם השם ידידיה, אהובו של ה׳.", ["ידידיה"])
n("יקירה", "יקירה היא צורת הנקבה של יקיר, ופירושה אהובה ויקרה. המילה באה מהשורש י־ק־ר, שעניינו ערך וכבוד, ומאותו שורש באות גם המילים יקר ויוקרה. בעברית של היום משתמשים במילה יקירה גם כפנייה חמה למישהי קרובה.", ["יקיר"])
n("כנרת", "כנרת הוא השם העברי של האגם הגדול בצפון הארץ, שמוכר גם בשם ים טבריה. בתנ״ך ים כנרת מסמן את הגבול המזרחי של הארץ. מקובל לקשר את השם לכלי הנגינה כינור, בגלל צורת האגם, אבל זה הסבר עממי. כנרת הוא גם שם של קבוצה ושל מושבה על חוף האגם.")
n("כתר", "כתר הוא עיטור שמלכים ומלכות שמים על הראש, סימן של שלטון ושל כבוד. בתנ״ך המילה מופיעה בצירוף כתר מלכות, שמשמש גם בעברית של היום. בהשאלה משתמשים במילה גם כשמדברים על מי שזכה בכתר בתחרות.")
n("לוטן", "לוטן הוא שם מקראי, שמופיע ברשימת בני שעיר החורי, שישבו בארץ אדום. השם נשמע קרוב למילה העברית לוט, כיסוי ועטיפה, אבל הפירוש שלו לא ברור. לוטן הוא גם שם של קיבוץ בערבה הדרומית.")
n("לינדה", "לינדה היא מילה בשפה הספרדית ובפורטוגזית שפירושה יפה ונאה. כשם היא מוכרת גם באנגלית ובשפות נוספות, ושם יש לה גם הסבר אחר, משם גרמני עתיק. בעברית השם נכתב כמו שהוא נשמע, בלי שינוי.")
n("לית'", "לית' היא מילה ערבית לאריה, ובערבית יש לאריה כמה שמות, וזה אחד מהם. המילה קרובה למילה העברית ליש, אחד השמות של האריה בעברית העתיקה. השם נכתב בעברית גם ליית', והגרש מסמן צליל ערבי שאין לו אות בעברית.", ["ליית'"])
n("מוחסן", "מוחסן הוא שם ערבי מהשורש ח־ס־נ, שעניינו טוב ויופי, ופירושו מי שעושה טוב לאחרים. מאותו שורש נבנו בערבית גם חסן, חוסני ואחסאן. בערבית המילה מוחסן משמשת גם לתיאור של מי שנותן ועוזר.")
n("מיטל", "מיטל בנוי מהמילים מי וטל, ופירושו מי הטל, המים של הטל. טל הוא טיפות המים הקטנות שמופיעות על הצמחים בבוקר, ובארץ הוא חשוב במיוחד בקיץ, כשאין גשם. השם נבנה בעברית החדשה, כמו שמות נוספים שנבנו על המילה טל, כמו טליה ואביטל.")
n("מייקי", "מייקי היא צורת חיבה אנגלית של מייקל, הצורה האנגלית של השם העברי מיכאל. באנגלית מקובל להוסיף לשם את הסיומת ־י כדי ליצור ממנו צורה קצרה וחמה. מיכאל עצמו בנוי מהמילים מי, כמו ואל, ופירושו מי כמו אל.", ["מייקל", "מיכאל"])
n("מילאד", "מילאד היא המילה הערבית ללידה, ובאה מהשורש ו־ל־ד, שהוא אותו שורש של המילים העבריות ילד ולידה. בערבית של היום המילה משמשת גם בצירוף שפירושו יום הולדת. כשם, מילאד מביא את הרעיון של התחלה חדשה.")
n("מליכה", "מליכה היא צורה של מלכה, שבנויה על השורש מ־ל־כ, שעניינו שלטון ומלוכה. בערבית מליכה פירושה מלכה, והשם מוכר בצורה הזאת גם בעברית. מאותו שורש נבנו גם השמות מלכה ומילכה, ובכל אחד מהם התנועות נשמעות מעט אחרת.", ["מלכה", "מילכה"])
n("מלכות", "מלכות היא שלטון של מלך או של מלכה, וגם הארץ שעליה הם שולטים. המילה באה מהשורש מ־ל־כ, ומאותו שורש באות גם המילים מלך, מלכה ומלוכה. בעברית משתמשים במילה גם בהשאלה, לתיאור של דבר מפואר ומרשים, כמו בביטוי יחס של מלכות.")
n("ממדוח", "ממדוח הוא שם ערבי מהשורש מ־ד־ח, שעניינו שבח, ופירושו מי שמשבחים אותו, משובח. מאותו שורש באה בערבית גם המילה מדיח, שיר של שבח. השם נבנה בתבנית ערבית של שמות שמתחילים במ־, כמו מחמוד ומנסור.")
n("מתי", "מתי הוא צורה קצרה של מתתיהו, שם עברי שבנוי מהמילה מתת, מתנה, ומיהו, צורה של שם ה׳. מאותו שם באים גם השם הארמי מתיא וצורות רבות בשפות של אירופה, כמו מתיאס ומתיו. כשם, מתי נשמע אחרת ממילת השאלה, עם דגש באות ת.", ["מתתיהו", "מתיא"])
n("נדאא", "נדאא היא המילה הערבית לקריאה, הקול שבו פונים למישהו וקוראים לו. השורש הערבי של המילה עניינו קריאה בקול ופנייה למישהו. כשם, נדאא מביא תמונה של קול שקורא ומזמין, ובעברית השם נכתב עם שתי אותיות א בסוף.")
n("נהרי", "נהרי בנוי על המילה נהר, עם הסיומת ־י, ופירושו הנהר שלי. נהר הוא זרם גדול של מים שזורם בין גדות, כמו הירדן בארץ. מאותה מילה נבנה גם השם נהר, ובעברית השורש נ־ה־ר קשור גם לאור, כמו במילה נהורה.", ["נהר"])
n("נחלה", "נחלה היא ירושה, חלק של אדמה או של רכוש שעובר מדור לדור. המילה באה מהשורש נ־ח־ל, ומאותו שורש באות גם המילים להנחיל ומנחיל. בעברית של היום משתמשים במילה גם בהשאלה, לתיאור של דבר שעובר מההורים לילדים, כמו שפה או מסורת.")
n("סאיד", "סאיד הוא שם ערבי שפירושו מאושר, מי שטוב לו ומרגיש שמח. כשם, סאיד מביא את הרעיון של חיים טובים ושל שמחה. בעברית השם נכתב באות א אחרי הסמך, כמו שהוא נשמע בדיבור.")
n("סופי", "סופי היא צורת חיבה של סופיה, שם יווני שפירושו חוכמה. בצרפתית ובשפות נוספות של אירופה סופי נעשה שם בפני עצמו, שמוכר כבר זמן רב. מאותה מילה יוונית באה גם המילה פילוסופיה, אהבת החוכמה.", ["סופיה", "סופיא"])
n("סעוד", "סעוד הוא שם ערבי מהשורש ס־ע־ד, שעניינו מזל טוב ועלייה, ופירושו הצלחה ושגשוג. מאותו שורש באים בערבית גם השמות סעיד וסעד. בעברית יש מילה קרובה, סעד, שפירושה תמיכה ועזרה, אבל המשמעות שלה אחרת.")
n("עזאת", "עזאת היא מילה ערבית שפירושה כבוד וגדולה, והיא באה מהשורש ע־ז־ז, שעניינו חוזק וכבוד. השורש משותף לערבית ולעברית, ובעברית ממנו באות המילים עוז ועזוז. השם נכתב בעברית גם עזת, באותה משמעות.")
n("עטא", "עטא היא מילה ערבית שפירושה מתנה, דבר שנותנים בלב רחב. היא באה מהשורש הערבי ע־ט־ו, שעניינו נתינה. כשם, עטא מביא את הרעיון של נתינה ושל נדיבות, ובעברית השם נכתב גם עטאא, באותה הגייה.")
n("עפאף", "עפאף היא מילה ערבית שפירושה צניעות וטוהר, התנהגות עדינה ומאופקת. היא באה מהשורש הערבי ע־פ־פ, שעניינו הימנעות ושמירה על עצמך. כשם, עפאף מביא את הרעיון של עדינות ושל פשטות.")

